// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 08 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd103569": "В далеком будущем возвращающийся на Землю грузовой космический корабль перехватывает исходящий с неизвестной планеты сигнал. Экипаж, в соответствии с основными инструкциями, обязан найти и исследовать источник сигнала. Оказавшись на планете, астронавты повсюду обнаруживают предметы, по виду напоминающие гигантские коконы.",
 "f-wd113244935": "Одинокий и повзрослевший Питер Паркер полностью посвящает себя борьбе с преступностью в Нью-Йорке, поскольку 4 года назад после заклинания Доктора Стрэнджа мир и все близкие забыли его. Но с ростом угроз и нагрузки на Человека-паука, его способности претерпевают странные изменения, способные поставить под угрозу его существование. Тем временем в городе случается новая цепочка преступлений, которая приводит к появлению одного из самых опасных противников в жизни Питера.",
 "f-wd55178974": "После уничтожения острова Нублар динозавры вырвались на свободу и заполнили планету. Людям удается поддерживать хрупкое равновесие, определяющее мирное сосуществование на Земле. Но как долго человек сможет сохранять свое господство, живя по соседству с самыми устрашающими существами в истории?",
 "f-wd56881169": "Прошло много лет с тех пор, как мальчик-ясновидец Дэнни Торранс пережил кошмарный сезон в отеле «Оверлук», где стал свидетелем безумия и гибели своего отца. Повзрослев, но не оправившись от детской травмы, Дэнни ведёт жизнь маргинала-алкоголика. С ним устанавливает связь другая «сияющая» девочка, Абра. Ей потребуется помощь Дэнни, чтобы не стать жертвой так называемого «Истинного Узла» — группы охотников за одарёнными детьми.",
 "f-wd52951815": "Суперкиллер Джон Уик после нарушения кодекса тайной гильдии ассасинов получает статус изгоя — экскомьюникадо. За его голову назначена цена в 14 миллионов долларов, и армия самых жестоких профессиональных убийц со всего мира открывает на него кровавую охоту.",
 "f-wd492908": "Недалекое будущее. 17 лет назад на планете произошла техногенная катастрофа. Там, где раньше росли леса и цвели сады, теперь лежат снег и лёд, и жизнь сохранилась лишь в гигантском поезде, без остановки мчащемся по трансевразийской магистрали. В первых вагонах состава живёт правящая элита, в последних — простые люди. Жизнь в хвосте поезда напоминает концлагерь — болезни, нищета и беспредел надсмотрщиков. Именно здесь из среды униженных и оскорблённых восстает человек, жаждущий восстановить справедливость.",
 "f-wd182153": "Неукротимый в своем желании всегда и во всем побеждать гоночный автомобиль «Молния» Маккуин вдруг обнаруживает, что сбился с пути и застрял в маленьком захолустном городке Радиатор-Спрингс, что находится где-то на трассе 66 в Калифорнии. Участвуя в гонках на Кубок Поршня, где ему противостояли два очень опытных соперника, Маккуин совершенно не ожидал, что отныне ему придется общаться с персонажами совсем иного рода. Это, например, Салли — шикарный Порше 2002-го года выпуска, Док Хадсон — легковушка модели «Хадсон Хорнет», 1951-го года выпуска или Метр — ржавый грузовичок-эвакуатор. И все они помогают Маккуину понять, что в мире существуют некоторые более важные вещи, чем слава, призы и спонсоры…",
 "f-wd244963": "Он — эксперт. Эксперт по оружию, ножам и собственному телу. Он человек, специально обученный не замечать боль и погодные условия. Во Вьетнаме его задание было уничтожать вражеский личный состав. Много убивать. Истощать силы врага до полной победы. Рэмбо был лучший. На войне он был героем, а на родине, во имя которой поливалась кровь, он никому не нужен. Не способный приспособиться к мирной жизни Рэмбо путешествует автостопом по городам Америки, встречаясь с однополчанами. Путешествие прекращает провинциальный шериф, ненавидящий бродяг. Попавший в тюрьму по ложному обвинению, вкусивший унижений со стороны администрации, Рэмбо объявляет войну. Войну существующему отношению к ветеранам, беспределу официальных структур и главе местной полиции лично. Совершив фантастический побег из тюрьмы, Джон начинает партизанскую войну в местных лесах. Очень скоро ситуация выходит из под контроля властей и в маленький город вводят части регулярной армии.",
 "f-wd63630439": "В конце 1967 года после гибели родителей мальчик переезжает жить к бабушке. Та вскоре замечает, что в их городке отираются ведьмы, которые не прочь превратить её внука в какое-нибудь животное, поэтому решает спрятаться в самом шикарном отеле Алабамы, где работает её кузен. Бабуля думала, что там они встретят только скучающих богатых постояльцев, но именно в этом отеле решает устроить тайный шабаш Величайшая Самая Главная Ведьма.",
 "f-wd63398229": "Янг — любимая игрушка в семье Джейка — ломается и не подлежит гарантии. Проблема в том, что Янг — это андроид, не отличимый от настоящего человека, и расстаться с ним не так просто. Джейк обещает дочери во что бы то ни стало починить Янга, и пускается в настоящую одиссею по волнам памяти робота, который окажется куда человечнее.",
 "f-wd115818765": "Маленькие брат с сестрой просыпаются посреди ночи и обнаруживают, что в их доме что-то происходит — родители ведут себя странно, а разные предметы, в том числе окна и двери, начинают исчезать. Новое абсолютное зло, именуемое «Скинамаринк», вырвалось на свободу.",
 "f-wd27894574": "«Богемская рапсодия» — это чествование группы Queen, их музыки и их выдающегося вокалиста Фредди Меркьюри, который бросил вызов стереотипам и победил условности, чтобы стать одним из самых любимых артистов на планете. Фильм прослеживает головокружительный путь группы к успеху, благодаря их культовым песням и революционному звуку, практически распад коллектива, поскольку образ жизни Меркьюри выходит из-под контроля, и их триумфальное воссоединение накануне концерта Live Aid, ставшем одним из величайших выступлений в истории рок-музыки. Фильм цементирует наследие группы, отношения внутри которой всегда были больше похожи на семейные, и которая продолжают вдохновлять неудачников, мечтателей и любителей музыки по сей день.",
 "f-wd1460092": "Действие разворачивается спустя шесть лет после того, как спутник NASA упал где-то в Центральной Америке, превратив пол-Мексики в карантинную зону. Сюжет следует за американским журналистом, согласившимся сопровождать туриста через зараженную зону к безопасным границам США.",
 "f-wd1199628": "Начинающая певица Флоранс обеспокоена своим здоровьем и, в ожидании результатов медицинского теста, она идёт к гадалке. Карты Таро показывают смерть, и, хотя гадалка пытается это скрыть, Клео окончательно теряет душевный покой. Не находя ни понимания, ни сочувствия своим тревогам, охваченная смятением, Клео не может оставаться дома и выходит на улицу. Она заходит в кафе, встречается с подругой, бродит по городу и знакомится с молодым мужчиной, который, гуляя по парку, прощается с мирной жизнью - он солдат и ему предстоит отъезд в Алжир, где идёт война...",
 "f-wd61876374": "Искусственный интеллект Entity готовится уничтожить человечество, постепенно перехватывая контроль над ядерными арсеналами мировых держав. У Итана Ханта и его команды есть лишь 72 часа, чтобы найти устройство с исходным кодом Entity, которое находится на затонувшей российской подводной лодке «Севастополь», и предотвратить глобальную катастрофу.",
 "f-wd87220566": "Фильм расскажет о том, как Николас Кейдж, чтобы заработать несколько миллионов долларов, отправляется на вечеринку на острове Мальорке, которую в честь своего дня рождения устроил криминальный авторитет Хави. Он большой фанат Кейджа и хранит у себя восковую фигуру актёра, а когда тот приезжает, обсуждает с ним кино — от «Кабинета доктора Калигари» до «Паддингтона 2».  Однако Хави не знает, что Кейджа завербовали агенты ЦРУ, которые с помощью актёра пытаются задержать главу преступного мира.",
 "f-wd38685497": "У сотрудника крупного банка всё идёт по накатанной, пока однажды он не выясняет, что окружающий его мир — это часть огромной видеоигры, а сам он в ней — всего лишь второстепенный персонаж. Хватит ли у него духу переписать свой код, обратить на себя внимание прекрасной девушки и, наконец, спасти мир? Одним словом, получится ли из него главный герой?",
 "f-wd24284363": "Великобритания, 1960-е годы. Эстелла была необычным ребёнком, и особенно трудно ей было мириться со всякого рода несправедливостью. Вылетев из очередной школы, она с мамой отправляется в Лондон. По дороге они заезжают в особняк известной модельерши по имени Баронесса, где в результате ужасного несчастного случая мама погибает. Добравшись до Лондона, Эстелла знакомится с двумя мальчишками — уличными мошенниками Джаспером и Хорасом. 10 лет спустя та же компания промышляет на улицах британской столицы мелким воровством, но Эстелла никак не может оставить мечту сделать карьеру в мире моды. Хитростью устроившись в фешенебельный универмаг, девушка привлекает внимание Баронессы, и та берёт её к себе в штат дизайнеров.",
 "f-wd10298666": "С момента примирения викингов и драконов прошло 5 лет. Пока Астрид, Сморкала и остальные ребята проводят время соревнуясь друг с другом в популярных на острове драконьих гонках, Иккинг и Беззубик путешествуют по небу, составляя карту неизвестных мест. Когда одно из их приключений приводит к открытию тайной ледяной пещеры, которая является домом для сотен ранее невиданных диких драконов и таинственного драконьего всадника, два друга оказываются в центре битвы за защиту мира.",
 "f-wd132731331": "После внезапной смерти Уилла, его жена Элис приезжает в уединённый семейный дом, чтобы пережить трагедию вместе с его семьёй. Однако вскоре выясняется, что смерть Уилла была не случайностью — перед гибелью он столкнулся с Джессикой, одержимой девушкой, которая передала ему демоническую силу. Уже после смерти Уилл возвращается и заражает собственного отца, превращая семейное прощание в кровавый кошмар. Пока одержимые один за другим охотятся на оставшихся членов семьи, Элис пытается защитить себя и понять, как остановить эту демоническую силу.",
 "f-wd729794": "Дэвид Вагнер — дитя девяностых. Но он увлечен телевизионным шоу «Плезантвиль», где действие происходит в 50-е годы в небольшом одноименном городке, где все шикарны, веселы и непорочны, и жизнь удивительно приятна.",
 "f-wd110819073": "Джон Кинли не помнит, как выжил, попав в окружение врага в Афганистане, но понимает, что обязан жизнью местному переводчику по имени Ахмед. Именно ему удалось отбить раненого Кинли и на себе вытащить через опасную территорию. Теперь чувство долга не даёт Джону покоя и он решает рискнуть всем, чтобы вернуться за Ахмедом и его семьёй. На обоих объявлена охота, действовать приходится в одиночку, но он понимает, что не может бросить своего товарища в беде...",
 "f-wd116547790": "Кларк Кент, родившийся на планете Криптон, но выросший в простой американской семье, считает своим долгом служение человечеству в качестве Супермена. Он предотвращает вторжение сил Боравии в соседнюю страну, чем навлекает на себя гнев Лекса Лютора, который со своими приспешниками проникает в Крепость Одиночества Супермена и очерняет его перед общественностью.",
 "f-wd115475669": "1942 год. Офицер Красной Армии Николай Киселев получает приказ вывести с оккупированных белорусских земель за линию фронта свыше двухсот евреев – стариков, женщин и детей, чудом избежавших неминуемой жестокой расправы. Этим истощенным, измученным голодом и страхом людям, потерявшим родных и едва не сошедшим с ума от пережитого ужаса, предстоит пройти пешком по лесным тропам сотни километров, чтобы вновь обрести надежду на спасение и веру в будущее...",
 "f-wd109745505": "Великая Отечественная война. В СССР идут тяжелые бои, немецкая армия наступает. В смешанный авиационный полк прибывает подразделение летчиц. Все они — юные, необстрелянные и сперва не совсем понимают, что такое война. Девушкам приходится трудно в мужском мире, но они день за днем в череде воздушных схваток доказывают, что они не хуже мужчин.",
 "f-wd51668": "Попытка детально воссоздать последние двенадцать часов из жизни Иисуса Христа.",
 "f-wd24797403": "Эльфаба, которая с самого детства подвергалась нападкам из-за своей зелёной кожи, заводит дружбу с популярной Глиндой в университете Шиз страны Оз. Но после встречи с Удивительным волшебником Оз их дружба подвергается испытанию.",
 "f-wd3574924": "1983 год. Телевизионный редактор Соня и переводчик из Франции Андрэ встретились в Москве и полюбили друг друга. У Сони есть сын-подросток и муж, успешный писатель. У Андрэ тоже есть семья в Париже. И вдруг для них исчезло все, кроме внезапно нахлынувшей страсти. Несколько дней своей жизни они были абсолютно счастливы, однако боги не остались равнодушными…",
 "f-wd4134604": "Что такое нофелет? Это разъяснит вам один из героев фильма — Гена, который взялся с помощью нехитрого приёма в два счёта найти невесту своему двоюродному брату Паше, сорокалетнему холостяку. В итоге Гена остаётся в дураках, а Паше надоедает попадать в смешные ситуации, и он сам находит выход их положения...",
 "f-wd119206814": "Чарльз Хеллер - криптограф ЦРУ, чья жена погибает во время теракта в Лондоне. Однако его начальство затягивает расследование, поэтому Хеллер решает самостоятельно заняться поиском террористов. Так как у него нет необходимых навыков, он шантажирует агентство, чтобы его отправили на специальное обучение.",
 "f-wd111784581": "1956 год, Франция. Священник убит, зло распространяется, и сестра Ирен вновь сталкивается лицом к лицу со злобной силой Валака, монахини-демона.",
 "f-wd189875": "Убежав из дома, Алиса увидела под старой яблоней большого белого кролика, одетого в куртку и жилет. Достав из кармана часы, кролик торопливо скрылся в подозрительно темной норе. Набравшись смелости, Алиса шагнула вслед за ним... и попала в чудесный сказочный мир, где сбываются самые несбыточные фантазии. Чтобы попасть обратно домой, Алисе придется совершить путешествие через весь этот странный и причудливый мир, в котором ее поджидают совершенно невероятные приключения и совершенно фантастические существа...",
 "f-wd223359": "Попугай-зануда оставляет свою уютную сытую жизнь в клетке и из Миннесоты отправляется в Рио-де-Жанейро, город грез всех и каждого. Неминуемые встречи, препятствия, опасности и любовь к последней представительнице его рода заставляют нашего героя по-другому посмотреть на мир и из скучного домоседа превратиться в милого симпатягу, узнавшего цену дружбе и смелости.",
 "f-wd160560": "Гарвардского профессора Роберта Лэнгдона подозревают в чудовищном преступлении, которого он не совершал. Лэнгдон знакомится с криптографом парижской полиции Софи Невё и вместе с ней пытается раскрыть тайну, которая может подорвать могущество католической церкви.",
 "f-wd182373": "1957 год, разгар холодной войны. Советские солдаты, возглавляемые агентом Ириной Спалько, похищают Мэрион Рэйвенвуд - давнюю возлюбленную Индианы Джонса, ставя профессора перед выбором: бездействие и смерть Мэрион или помощь советской разведке в поисках легендарного Хрустального черепа в обмен на свободу женщины.",
 "f-wd245227": "Эта история случилась на заре цивилизации в Древнем Египте. Стремительный и величавый Нил вынес на берег перед дворцом фараона корзину с младенцем. Могущественный правитель усыновил крошечного мальчика и дал ему имя Моисей.  Шли годы… Моисей и его брат Рамзес росли вместе. Но придет день, когда один из братьев станет владыкой величайшей империи на земле, а другой — святым… Противоборство героев навсегда изменит их судьбы и историю человечества.",
 "f-wd243643": "1891 год. В Вене и Страсбурге проходит серия терактов, организованных анархистами или националистами, а по всей Европе происходят таинственные убийства. Шерлок Холмс считает, что за всем этим стоит профессор Джеймс Мориарти — математический гений, автор знаменитых лекций и трудов.",
 "f-wd754736": "Студия Уолта Диснея преподносит отличный подарок — девять коротких музыкальных историй, объединенных в один сборник «Необыкновенный концерт». Невероятно милые, под час забавные рассказы великолепно дополнены песнями и музыкой в исполнении известнейших певцов и биг-бендов 40-50 годов. Прекрасная музыка, замечательная анимация и искрометный юмор — в лучших традициях знаменитой студии Уолта Диснея!",
 "f-wd107914": "На этот раз Джеймсу Бонду поручено расследовать похищение огромной партии южноафриканских алмазов. Распутывая это непростое дело, Бонд выходит на след своего заклятого врага Блофельда.",
 "f-wd747570": "Бывший солдат Джерри пытается стать художником в послевоенном Париже. И имеет некоторый успех, найдя богатую покровительницу, которая покупает его картины и рекомендует их своим друзьям. Однажды он заходит в ночной клуб и знакомится с Лизой и молодые люди моментально влюбляются. Но позже она неожиданно сообщает, что помолвлена с его другом. И Джерри, и Лиза поступают благородно, решив более не встречаться.",
 "f-wd108671102": "Работая под землёй над ремонтом водопровода, бруклинские сантехники - братья Марио и Луиджи, спускаются по таинственной трубе и попадают в волшебный новый мир. Но когда братья разлучаются, Марио отправляется в эпическое путешествие, чтобы найти Луиджи.",
 "f-wd25043": "Король Артур и рыцари Круглого стола отправляются в невероятное путешествие на поиски Святого Грааля. В пути они попадают в самые нелепые и абсурдные ситуации.",
 "f-wd5516100": "После того как Доминик и Брайн побывали в Рио, где они ограбили и свергли империю вора в законе, их команда получила 100 миллионов, и наши герои оказались разбросаны по всему миру. Но их привычка вечно жить в бегах не даёт им покоя. Между тем, Хоббс отслеживал организацию смертельно опасных наёмников-водителей по двенадцати странам. Единственный способ остановить эту криминальную группу — это превзойти их на улицах, поэтому Хоббс просит Дома собрать его элитную команду в Лондоне. За это он обещает полное помилование для Доминика и его друзей, чтобы они смогли наконец вернуться домой к своей семье.",
 "f-wd487447": "Панда По наконец-то исполнит свою мечту, станет Воином Дракона и со своими друзьями и мастерами кунг-фу — Неистовой Пятеркой — защитит Великую Долину от страшного злодея и его легиона…",
 "f-wd320423": "Спасая мир от безумного злодея Стромберга, который разрабатывает план по уничтожению жизни на земле с помощью сверхмощного звука, Джеймс Бонд знакомится с очаровательной русской разведчицей. Вместе они вступают в неравную схватку с негодяем и его преданным слугой Джозом. Это по-настоящему гигантского размера детина с железными зубами, которыми он с легкостью перекусывает толстый стальной трос. Для того, чтобы уравнять силы, Бонду предоставляют абсолютно эксклюзивный спортивный автомобиль «Лотос»",
 "f-wd221236": "Восьмая часть всемирно известного сериала о приключениях бесстрашных звездолетчиков в далеком будущем. Посланцы враждебной инопланетной цивилизации проникают в прошлое, и первый контакт человечества с внеземным разумом, способный положить начало новой космической эры, оказывается под угрозой срыва.  Перед экипажем легендарного космического корабля «Энтерпрайз» и его мужественным капитаном Пикардом стоит трудная и опасная задача — помешать осуществлению планов врага и спасти будущее Земли.",
 "f-wd867283": "Жители тихой американской провинции становятся свидетелями ослепительной вспышки и падения огромного летающего объекта. Спустя несколько дней мальчуган по имени Хогарт Хьюз находит в окрестностях гигантского робота, прилетевшего на Землю из далёкой космической галактики. Несмотря на свой грозный вид, инопланетный гость оказывается добрейшим созданием. Между ним и отважным мальчишкой завязывается настоящая дружба. Но узнавшие о существовании робота правительство и военные решили уничтожить пришельца. Хогарт — единственный, кто может спасти стального гиганта...",
 "f-wd308681": "Родители Юрия и Виталия Орловых покинули Украину и обосновались в Америке: у них маленький ресторанчик на Брайтон-Бич. Дети же не стремятся идти по родительским стопам. Юрий начинает торговать оружием и с помощью брата быстро завоевывает свое место под солнцем. Но чем выше он поднимается, тем ближе к нему подбирается агент Интерпола.",
 "f-wd658041": "Каждое утро Луизе приходится ходить в один и тот же ресторан быстрого обслуживания — она работает там официанткой. У неё есть «бойфрэнд» — музыкант, который, гастролируя по придорожным забегаловкам, частенько забывает о своей возлюбленной. Энергичная и в прошлом жизнерадостная Тельма, выйдя замуж за Дэррила, обнаружила, что место женщины — на кухне с кастрюлями, а мужчины — в кресле перед телевизором.  Само собой такая жизнь не устраивает женщин, и в один прекрасный день чаша их терпения переполняется. Они решают уехать подальше из «осточертевшего» городка и от своих ненавистных мужчин. К сожалению, по дороге им приходится совершить ряд преступлений, в том числе и убийство. Их объявляют в розыск по всей Америке, и подружкам остаётся только одно — любыми способами успеть добраться до Мексики.",
 "f-wd278997": "В основу этой приключенческой ленты положен роман Дэниела Уоллеса «Большая рыба: роман мифических пропорций». Умирает отец, о жизни которого сын хочет узнать как можно больше, собирая истории о нем. Сын пытается воссоздать ускользающую жизнь отца в серии легенд и мифов, которые тот придумывает на основе разрозненных фактов. Взлеты и падения в жизни человека в итоге предстают в неожиданном ракурсе.",
 "f-wd720724": "История о приключениях маленького необыкновенно умного поросенка йоркширской породы. Все животные на ферме Хоггетов имеют ярко выраженную индивидуальность и общаются между собой на человеческом языке. Люди при этом, разумеется, совершенно не в курсе дела.\r Когда же хозяин начинает что-то подозревать, он сам включается в эту игру, надеясь использовать в хозяйстве вдруг проявившийся интеллект животных. Четвероногий малыш, тот самый поросёнок, воспитанный овчаркой Флай, пытается доказать, что свинья годится не только для украшения рождественского стола (к чему дело как раз и шло), но способна выполнять работу, требующую ума и сообразительности — пасти овец.\r Можете себе представить, как к этой идее относятся сами овцы! Не говоря об овчарках — какая профессиональная гордость такое выдержит?",
 "f-wd382320": "Трое мужчин и женщина купили украденную для них новейшую микросхему, способную нейтрализовать всю систему противокосмической обороны. Положили ее в игрушечную машину, ее — в пакет с надписью «Parisian». В аэропорту обнаружилось, что в пакете игрушки нет, а вокруг ходят люди точно с такими же пакетами. Стали искать. В результате поисков пришлось лететь за пакетом в Чикаго. Самые догадливые зрители уже, наверное, догадались, в чей дом привезла пожилая дама пакет с игрушкой. Ну, конечно же, туда, где живет маленький милый мальчик. Все знакомо? Да, только на этот раз вместо незадачливых бедолаг-неудачников против мальчугана, заболевшего скарлатиной и оставшегося дома, выступают настоящие профессионалы, люди очень и очень опасные. А другие серьезные люди, у которых микросхема пропала, тоже сидеть без дела не намерены.",
 "f-wd390097": "Кровавый период Гражданской войны в США: американский конфедерат Инман пытается добраться с линии фронта домой, в Холодную Гору (штат Северная Каролина), где оставил свою возлюбленную Аду. Ада пытается выжить одна в разоренном тылу. На помощь ей приходит бродяжка Руби, которая учит светскую барышню азам ведения хозяйства…",
 "f-wd24075": "Из тихоокеанских джунглей на Нью — Йорк надвинулась страшная катастрофа. На глазах у потрясенных жителей рушатся небоскребы, переворачиваются автобусы, уходят под землю целые кварталы. Но это не ураган и не землетрясение. Это — Годзилла, самое ужасное чудовище в истории.Для него человеческая цивилизация — лишь жалкий муравейник, дома — спичечные коробки, вертолеты — назойливые стрекозы. Мегаполису грозит полное уничтожение. Армия, оснащенная по последнему слову техники, не в силах противостоять гигантской ящерице. Небольшой группе смельчаков предстоит выяснить, зачем Годзилла пришел в Нью — Йорк. Возможно, тогда им удастся спасти город…",
 "f-wd221852": "Документальное исследование причастности Джорджа Буша к трагедии 11 сентября… Главные темы фильма — истоки терроризма и события 11 сентября 2001 года. В фильме Мур расследует тесные связи, существовавшие между двумя «кланами», двумя поколениями Бушей и двумя поколениями бен Ладенов. Автор картины утверждает, что между Джорджем Бушем-старшим и отцом Усамы бен Ладена существовали прочные деловые связи. Они сложились, когда Буш-старший еще находился на посту президента США, долгое время поддерживались и были разорваны лишь через два месяца после чудовищных терактов, осуществленных против США в 2001 году.",
 "f-wd93853": "Этот фильм — продолжение истории о гитаристе Эль Марьячи. На этот раз он пытается помешать могущественному наркобарону Баррильо свергнуть президента Мексики.Это задание он получает от продажного агента ЦРУ Сэндса, который не хочет рисковать собственной жизнью ради спасения жизни главы чужого государства. Приключения Эль Марьячи начинаются на фоне грядущей революции, всеобщей неразберихи и кровной мести.Главный герой, ставший известным благодаря превосходной игре Антонио Бандераса, великолепно справляется как с гитарой, так и с пистолетом, и, несмотря на все трудности и раны, всегда добивается успеха.",
 "f-wd819972": "Бывший десантник Фрэнк Мартин имеет неплохой бизнес - перевозит любые грузы по французскому Средиземноморью и делает свою работу быстро и качественно. Недостатка в клиентах нет, ведь, он всегда неукоснительно соблюдает три правила: не меняет условий сделки, не спрашивает никаких имен и никогда не заглядывает в багаж. Но однажды, перевозя груз клиента по имени Уолл Стрит, Фрэнк обнаруживает, что мешок шевелится.",
 "f-wd175014": "История о 12-ти присяжных, обсуждающих, виновен ли 18-летний юноша, обвиняемый в убийстве своего отчима — офицера Российской армии, воевавшего в Чечне. Все улики свидетельствуют против обвиняемого, и одиннадцать из двенадцати человек, собравшихся в школьном спортзале, готовы осудить юношу. Но один из присяжных уверен, что всё не так однозначно, как кажется на первый взгляд, и предлагает коллегам более вдумчиво рассмотреть дело.",
 "f-wd29355": "Привычный ход вещей нарушен! Цирковая собака Белка больше не выйдет на манеж покорять сердца зрителей, а дворняжка Стрелка не будет ночевать в подворотнях и искать себе пропитание. Теперь они не просто собаки, а члены отряда космонавтов. И лишь самые достойные, самые выносливые отправятся покорять космическое пространство.",
 "f-wd83487969": "1942 год, оккупированная Европа. Оказавшись в концлагере, бельгиец еврейского происхождения Жиль Кремье выдает себя за перса — для него это единственная возможность остаться в живых. Это ложь действительно спасает ему жизнь, но Жиль еще не представляет, какой ценой. Довольные таким редким уловом немецкие солдаты приводят Жиля к концлагерному повару Клаусу Коху, который мечтает, как только закончится война, уехать в Иран и открыть там ресторан. Кох ищет настоящего перса, который научит его говорить на персидском языке. Так начинается история Жиля Кремье и Клауса Коха — еврея и немца, узника и тюремщика, учителя и ученика.",
 "f-wd2527730": "Четыре новеллы, посвященные судьбе острова Куба и его борьбе за независимость от США. Каждая из новелл демонстрирует непоколебимый дух кубинского народа, однажды восставшего против колониальной диктатуры правящего политического режима. Доведенный до отчаяния народ решился на революцию, возглавленную Фиделем Кастро, и ставшую в итоге освободительной. «Я — Куба» — драма совместного производства СССР и Кубы. Двухсерийный фильм снят при помощи ручной камеры.",
 "f-wd940081": "В одной из римских больниц скончалась русская эмигрантка. Старая дама, некогда эмигрировавшая из России, поведала своей внучке Ольге, что все ее огромное состояние спрятано в Ленинграде «под львом». Это обстоятельство явилось причиной срочного отлета в Ленинград всех тех, кто случайно или специально был посвящен в эту тайну. В СССР прибыли солидный врач, итальянский мафиози, два санитара, просто горожанин и внучка Ольга. А в Москве к ним присоединился еще и гид, который усложнил и так непростые поиски сокровищ…",
 "f-wd2995252": "1565 год. Темные времена. Правление Ивана Грозного. Русь растерзана голодом и ливонской войной. Во всем мерещатся правителю измена и предательство. Его верные слуги, опричники, залили страну кровью. В каждом готовы они увидеть государева врага. Главный закон для них - царь. Единственный, кто пошел против царской воли и опричных злодейств, - митрополит Филипп, верный друг детства Ивана Грозного. Он возвысил голос свой и принес себя в жертву. Это противостояние расскажет о том, на что была способна Русь и в падении и в величии духа.",
 "f-wd1678442": "Осенью 1952 года шестилетний Санька и его молодая мама знакомятся в поезде с красавцем военным по имени Толян. Катя влюбляется в Толяна, и все вместе они начинают жить одной семьей. Но на поверку этот бравый и обаятельный офицер оказывается вовсе не отставным военным, а профессиональным вором…",
 "f-wd2634496": "22 июня 1941 года в 3 часа 30 минут фашистская Германия вероломно напала на Советский Союз. Суровым было начало Великой Отечественной войны. Красная Армия с жестокими боями отходила вглубь страны. Однако в самые трудные времена советский народ не покидала вера в победу. Уже в сорок первом году план молниеносной войны, разработанный германским командованием, был перечёркнут героическим отпором советских людей. Во всём содержании киноэпопеи прослеживается идея превосходства военного таланта полководца Георгия Жукова и героизма рядовых советских людей над нерешительностью и подозрительностью Иосифа Сталина и глупостью и трусостью части высшего командования Красной Армии в начале войны.",
 "f-wd2250645": "Дочь венецианского купца Дездемона тайно венчается с генералом венецианской республики мавром Отелло. Яго, слепо ненавидящий Отелло, намерен разрушить его счастье и убеждает генерала в неверности жены. Сжигаемый ревностью Отелло душит Дездемону. А затем, убедившись, что стал жертвою интриги, закалывает себя кинжалом.",
 "f-wd247713": "По мотивам одноименной арабской сказки. В Багдаде появлется злой волшебник-магрибинец. Колдовство открыло ему имя человека, который может найти лампу, способную творить чудеса. Это бедняк Аладдин, сын Али-Аль-Маруфа. Волшебная лампа, в которой живёт джинн остаётся в руках Аладдина. Благодаря ей он покоряет сердце капризной принцессы Будур и побеждает магрибинца.",
 "f-wd2581338": "Безлошадная крестьянка Марфа Лапкина, не желая больше мириться с нищетой, вместе с участковым агрономом и бедняками организует в деревне молочную артель. Рабочие-шефы помогают артели получить первый трактор. В финале картины десятки тракторов пашут артельную землю. За рулем одного из них - Марфа Лапкина.",
 "f-wd2707305": "Исторический фильм о борьбе албанского народа против турецких завоевателей в XV веке под предводительством Георгия Кастриота, прозванного турками Скандербегом. Сын князя, он еще мальчиком был отдан в заложники турецкому султану, где воспитывался как воин султаната. Через 20 лет службы турецкому престолу, любовь к родине заставляет его подняться на борьбу против своих поработителей.",
 "f-wd1976498": "Фильм рассказывает о событиях 1942, происшедших в оккупированном фашистами Краснодоне. Вчерашние школьники создают подпольную организацию и начинают свою борьбу: распространяют листовки, освобождают группу пленных красноармейцев, сжигают немецкую баржу, спасая соотечественников от фашистского рабства, в день годовщины Октября развешивают красные флаги. В их действиях, как и в их детском бесстрашии многое идет от игры: ведь еще вчера кое-кто был признанным хулиганом, кое-кто вовсе не помышлял о подвигах, кое-кто не желал выслушивать наставления, подчиняться дисциплине. Но именно благодаря их изобретательности, отчаянной смелости и дерзости удавались самые опасные и самые ошеломляющие акции. И именно их образы оказались наиболее полнокровными и яркими, живыми.",
 "f-wd4376329": "Накануне церковного праздника Святого Йоргена, вор Коркис совершает побег из тюрьмы с помощью сообщника Шульца. Увидев, сколько денег оседает в карманах священнослужителей, подельники задумывают кражу в храме.  Шульц крадёт ключ, впускает в церковь Коркиса и запирает дверь. Но он попадается на глаза полиции и вынужден притвориться инвалидом. Церковная процессия, подходящая к храму, застаёт Коркиса врасплох. Он быстро переодевается Святым Йоргеном и выходит навстречу толпе, жаждущей чудес. Он «исцеляет» Шульца и отпускает всем грехи бесплатно.",
 "f-wd718475": "СССР, шестидесятые годы… Сержант Виктор молод, статен, смотрит на жизнь просто и прагматично. Он готов на все, чтобы добиться в жизни своей цели — сделать карьеру. Пока удача способствует ему — его, курсанта привилегированной Кремлевской роты, крупный армейский генерал берёт своим личным водителем. Генерал Серов рассчитывает женить его на своей неудачливой дочери Вере. Вера — хромоножка. Но нового водителя Виктора это не слишком смущает. Он вырос сиротой в детском доме, в нищете. Теперь, за шанс пробиться «в высшие сферы», Виктор готов жениться на дочери генерала. А влюбчивая Вера не замечает холодного расчёта с его стороны. Странный их роман развивается на генеральской даче в Крыму под Севастополем. Ласковое солнце черноморского побережья, атмосфера шестидесятых с их музыкой, модами, машинами, с их бытом и развлечениями, будут соседствовать в фильме с тайной борьбой за сферы влияния между армией и КГБ.",
 "f-wd1528336": "Из занятой большевиками Москвы уезжает в Крым на съёмки звезда немого кино Ольга Вознесенская. Она остро переживает крушение старого мира, стоит перед мучительным выбором: принять перемены или бежать от них. Быть может, спасением для знаменитой актрисы окажется любовь?..",
 "f-wd477602": "Обстоятельства сводят в маленьком домике убийцу и случайно избежавших участи своих товарищей-золотоискателей мужа и жену Нельсон, становящихся его стражниками, судьями и палачами.",
 "f-wd1640074": "Время действия - Вторая мировая война. О солдатах и офицерах итальянских дивизий, взявших направление на Москву. Дорого даётся оккупантам каждый шаг... В этом походе погибает молодой солдат - крестьянин Бадзокки. И старшине Габриэлли не суждено больше увидеть родину: после многодневного мучительного продвижения он замерзнет в пустынном поле...",
 "f-wd2732154": "Фильм рассказывает историю одного человека - Ивана Саньшина, который был киномехаником Сталина. Он работал на Сталина с 1939 года и до смерти вождя. Основные действующие лица - сам Иван, его жена Анастасия и соседская девушка еврейка Катя. Родителей Кати репрессировали, и она оказалась привязанной к Анастасии.  В судьбе Ивана Саньшина происходит настоящая трагедия - его жена становится любовницей Берии и далее её судьба несколько туманна.",
 "f-wd4165536": "Дом на Трубной заселен мещанской, нэпмановской публикой. Парикмахер Голиков решает нанять домработницу, но только — не члена профсоюза. Его выбор падает на приехавшую из деревни в Москву Параню…",
 "f-wd1219544": "Много хороших мастеров на Урале, какие только диковинные вещицы не вырезают они из камня. Но лучше всех Данила-мастер. Не была отбоя от заказчиков у Данилы, но запал ему в душу цветок каменный.  Люди сказывали, кто увидит хоть раз этот цветок у Хозяйки Медной горы, тот навсегда покой потеряет, настолько хороша эта работа. И решил Данила отправиться в подземное царство и своими глазами увидеть это чудо невиданное. А увидев, позабыл и про белый свет, и про милую невесту…",
 "f-wd442853": "Фильм о спасении коллекции Дрезденской картинной галереи воинами Советской Армии в годы Второй мировой войны.",
 "f-wd4445162": "Биографический фильм о великом русском полководце генералиссимусе Александре Васильевиче Суворове, охватывающий период последних лет его жизни в эпоху царствования Павла I. В центре фильма — победа над войсками Наполеона, легендарный переход через Альпы",
 "f-wd21843161": "Редкий дар ввязываться во всевозможные неприятности — их семейная черта, да и что взять с тех, кто вырос среди снегов в компании троллей. Но повзрослев, Кай и Герда выходят на новый уровень — теперь они станут виновниками катастрофы мирового масштаба...",
 "f-wd251585": "Виктор Середа, школьный авторитет во всем, что касается точных наук, рассказывает о своем проекте полета к созвездию Кассиопеи на космическом корабле «Заря».  Собственно, ничего бы не произошло, если бы вдруг не появилась некая загадочная личность, представившая себя как И. О. О., что означает исполняющий особые обязанности.  Как выяснилось, из детей не старше 14 лет набирается команда (шесть человек) для… полёта в космосе. Почему дети должны быть младше 14 лет? Да потому, что полёт туда и обратно для детей займёт больше пятидесяти лет, а на Земле и то пройдут столетия. И всё бы шло по плану, если бы на корабле не оказался седьмой участник — тайком пробравшийся туда хулиган Федя Лобанов, создатель суперклея…",
 "f-wd3212859": "«Шестая часть мира» - пропагандистская картина, созданная по заказу внешнеторгового предприятия Госторг и популяризирующая экспортные возможности Советского Союза. Съемка фильмов о Госторге велась по всему Союзу: отстрел пушнины на Крайнем Севере, уборка льна на севере и в центральных районах, выращивание овец для выделки каракуля на Кавказе, выращивание хлеба в черноземных и южных житницах, погрузка товаров в крупнейших портах. В картине показана также революционная борьба рабочего класса.",
 "f-wd4345095": "Саратовский парень Сергей Луконин летом 1932 года уезжает из районного города в далекий Омск, в танковую школу. В Саратове остается его невеста, Варенька, вскоре ставшая актрисой. В 1936 году Сергей отправляется на войну в Испанию. Ранение, плен, побег и вновь учебные бои, а впереди — июнь 1941 года…",
 "f-wd1809073": "Cовременная версия одноименного фильма 1939 года. В центре истории — обеспеченная женщина, неподозревающая об интрижке своего мужа с какой-то продавщицей, плюс еще куча персонажей вроде любовниц, подруг и бывших. Со стороны казалось, что у Мэри Хайнс есть все основания считать себя счастливой и состоявшейся женщиной: у нее дом в Коннектикуте, милая 12-летняя дочь, муж — успешный бизнесмен с Wall Street — и карьера дизайнера в фирме отца. Ее лучшая подруга, Сильвия Фоулер, тоже была устроена в жизни — главный редактор журнала «Каше», шкаф, полный одежды с подиумов, статус «арбитра стиля и вкуса» в Нью-Йорке и агрессивная позиция холостячки, которая ее полностью устраивала. Или ей так казалось.",
 "f-wd2060015": "Лето 1994 — улицы Нью-Йорка пульсируют от хип-хопа и облака марихуаны двигаются своим путем… Нововыбранный мэр Рудольф Гулиани только начинает принимать меры против таких преступлений как громкое радио, рисунки на стенах и пьянство. Безумие показывает нам Люка Шапиро, студента и наркодилера, который подружился с доктором Джефри Сквиресом, психиатором и просто родственной душой. Когда доктор предложил Люку продать ему наркотик для сеансов терапии оба начинают исследовать глубины Нью-Йорка и своей депрессии.",
 "f-wd108760444": "Чики, чтобы морально поддержать друзей, воюющих во Вьетнаме, решает самолично угостить их американским пивом. Поездка, начавшаяся как спонтанная авантюра, в корне меняет его взгляды на жизнь и войну.",
 "f-wd124450734": "Линда испытывает трудности из-за загадочной болезни дочери. Поскольку её муж работает на морском судне и часто отсутствует, Линда вынуждена в одиночку ухаживать за ребёнком, который питается через зонд. Лечение девочки курирует врач, который критикует Линду за пропуски медицинских процедур и посещений. Несмотря на любовь к дочери, Линда не справляется с большим количеством обязанностей. Дополнительное напряжение создаёт появившаяся большая дыра в потолке их квартиры, которая приводит к протечке. В результате мать с дочерью вынуждены переехать в недорогой мотель на неопределённый срок в ожидании ремонта.",
 "f-wd28173308": "Фильм о группе британских офицеров в последнюю весну Первой мировой войны. Молодой и наивный лейтенант Рейли присоединяется на фронте к своему детскому кумиру и другу семьи, капитану Стэнхоупу, не подозревая, как тот изменился за годы службы. Их отряд теснится в окопах в ожидании сокрушительной атаки немцев.",
 "f-wd839596": "Так же, как и в знаменитой классической истории, главным героем фильма является Эдмон Дантес. Этого бесхитростного молодого человека, собирающегося жениться на красавице Мерседес, предает его лучший друг Фернан.  Оказавшись заключенным в тюрьму, Эдмон Дантес в течение тринадцати лет вынужден терпеть лишения и лелеять мысли о мести своим обидчикам. С помощью человека, сидящего с ним в соседней камере, Эдмону удается бежать из тюрьмы.  После этого он появляется в обществе в качестве богатого благородного и могущественного графа Монте-Кристо, который искусно и беспощадно расправляется с людьми, обманувшими и предавшими его много лет назад…",
 "f-wd122169131": "1950 год, в дом богатой неаполитанской семьи прямиком из Версаля доставили шикарную карету-кровать для младенца, который вот-вот родится прямо в водах Тирренского моря. На свет появилась девочка, и ее назвали Партенопой в честь древнегреческой нимфы, чьим именем когда-то нарекли Неаполь. Идеальная во всем девушка жила на полную катушку: меняла любовников и увлечения, пробовала начать карьеру актрисы, училась на антрополога и танцевала до утра. Блестящую жизнь любимицы судьбы омрачило лишь одно событие — суицид брата Рафаэля, затухшего в лучах яркой Партенопы.",
 "f-wd114345051": "Офисный работник всю жизнь строит по указаниям босса, но бунтует, когда тот предлагает ему устроить автокатастрофу. Полицейский безутешен, когда его жена-исследовательница пропадает в морской экспедиции, однако, когда та возвращается, начинает подозревать, что её подменили. Последователи культа, завязанного на сексе и солёной воде, по поручению своего гуру разыскивают девушку, способную воскрешать мертвых.",
 "f-wd185376": "Майору никак не присвоят звание полковника по одной причине — он умеет только убивать, ни на что другое он просто не способен. Его отправляют в отставку. Работа в полиции ему не подходит, и наш герой умирает от скуки в одном из номеров отеля.Неожиданно он получает предложение стать инструктором по военной подготовке в военном учебном заведении.",
 "f-wd666082": "Англия Викторианской эпохи. Богатый дворянин нанимает для своих племянников, осиротевших ещё в младенчестве, гувернантку мисс Гидденс — скромную молодую женщину из семьи священника. Уже в первые дни воспитательница начинает видеть призраки бывшего камердинера усадьбы мистера Квинта и своей предшественницы, гувернантки мисс Джессил.",
 "f-wd4528663": "Нестареющая сказка о любви, дружбе и чудесах, которые случаются под Рождество. Наступил Сочельник, канун Рождества, и все члены семьи Штальбаумов разворачивают свои подарки. Когда восторги улеглись, маленькая Мари получает еще один, весьма необыкновенный подарок — таинственного Щелкунчика.",
 "f-wd497622": "Сначала они кажутся призрачными, играя в прятки в загородном доме Фрилингов. Тучи сгущаются, ожившие деревья нападают, а малютку Кэрол Энн Фрилинг засасывает в спектральную пустоту. И пока её семья борется с вереницей кошмаров и пытается спасти девочку, где-то рядом затаилось нечто потустороннее.",
 "f-wd1219665": "Вольная экранизация древнегреческого мифа, в котором рассказывается о походе аргонавтов за золотым руном.",
 "f-wd2373306": "В 1960-е годы в уральский леспромхоз недалеко от Чусового приезжает работать поварихой Тося Кислицина. «Первый парень» посёлка лесоруб Илья спорит с приятелями, что Тося в него влюбится. Узнав о споре, Тося порывает с Ильёй, а парень, к немалому своему удивлению, понимает, что по-настоящему полюбил эту задиристую смешливую девчонку.",
 "f-wd2601067": "Агрессивный ребенок, влюбленный подросток, разочарованная жена - повествовательная головоломка переносит нас через пятнадцать лет жизни Викторины, ребенка из государственного дома, с ее радостями, горестями и проблемами. Когда она плывет по мутной воде среди душераздирающих или презренных персонажей, где расизм и глупость (как и везде) заметны, послание нежности и надежды появляется в глазах ребенка, а иногда даже в уголках бетона.",
 "f-wd126012569": "История чемпиона смешанных единоборстви UFC Марка Керра.",
 "f-wd4371720": "Снова мы встречаемся с безумным доктором Мортимером Гангрином, одержимым идеей мирового господства. На этот раз он намеревается устроить вторую Великую французскую революцию и для начала сделать правителем Франции своего помощника Игоря. На пути ненормального ученого встает американский герой и простая французская девушка…",
 "f-wd17893055": "Прошло три года после того, как Майк на пике своей популярности закончил карьеру стриптизера, а клуб «Короли Тампы» уже почти готов признать свое поражение. Но проделать это в своем стиле: готовясь «зажечь» Мёртл-Бич, они снова разделят сцену с легендарным Супер Майком. Дорога на последнее шоу проходит через Джеконсвилл и Саванну, где Майк и парни повстречают старых знакомых и заведут новых, а также выучат пару неизбитых движений, тряхнув при этом стариной.",
 "f-wd176488": "Некий шоу-бизнесмен устраивает в доме печально известного убийцы Майкла Майерса, считающегося мёртвым, действо, весьма напоминающее шоу «За стеклом». Группа подростков должна провести ночь в доме маньяка с трансляцией всего происходящего в интернет, из оборудования только е-майл.",
 "f-wd573104": "Это случилось в тот момент, когда счастливая семья — Пол, Джесси и их сын Адам — готовились к переезду в связи с приглашением Пола на другую работу. В день своего восьмилетия под колёсами автомобиля погиб Адам, сделав своих родителей глубоко несчастными людьми. На похоронах супругов окликнул незнакомец, оказавшийся известным учёным-генетиком Ричардом Уэллсом.  Уэллс сказал, что он в состоянии вернуть им сына в точности таким же, каков тот был при жизни, то есть клонировать его, использовав ген погибшего мальчика. Возмущенный Пол с негодованием отвергает кощунственное, с его точки зрения, предложение. Но Ричард оставляет Джесси свой телефон и советует подумать…",
 "f-wd17501972": "История рассказывает о героических усилиях криптозоологического агентства «Монарх» по сдерживанию гигантских монстров. В этот раз против могучего Годзиллы выступают Мотра, Родан и ультимативный кайдзю — трёхголовый монстр Кинг Гидора. Когда эти древние суперхищники, со временем превратившиеся в полузабытые мифы, восстают снова, чтобы сойтись в схватке, человечеству остаётся отойти в сторонку и постараться не погибнуть.",
 "f-wd19842552": "По миру катится волна убийств знаменитостей. Специальный агент модной полиции Монтана Гроссо обращается за помощью в расследовании к когда-то топовому, а ныне слегка потрепанному мужчине-модели Дереку Зуландеру. Сможет ли он в компании своего заклятого друга Ханселя остановить преступления на модной почве и триумфально вернуться на подиум в мире, где для обретения всеобщей популярности достаточно одного селфи?",
 "f-wd17984058": "Современный мир скрывает множество секретов, но самым удивительным из них является то, что ведьмы до сих пор живут среди нас. Это злобные сверхъестественные существа, чья цель — наслать на мир смертоносную чуму. Армии охотников на ведьм сражались с ними на протяжении многих веков.  В наши дни остался всего лишь один охотник на ведьм, Колдер, которому однажды удалось убить всемогущую королеву ведьм. Но Колдер еще не знает, что королева воскресла и жаждет отомстить своему убийце…",
 "f-wd25461297": "Главный герой, бывший морпех, обнаруживает злобную инопланетную расу на Земле, но никто не верит ему, что эти твари существуют. Его сын-аутист, которого все обижают в школе, становится ключевой фигурой в схватке с Хищниками, поскольку мальчик умеет невероятно быстро учить языки и, судя по всему, сможет понять пришельцев.",
 "f-wd514293": "В доперестроечные времена торговля наркотиками была из ряда вон выходящим преступлением. На борьбу с грузинским бандитом, который, используя связи в США, пытается пристрастить к кокаину советских граждан, выходит гроза преступного мира милиционер Иван Данко. Этот парень не любит шутить, и доказательством серьезности его намерений служат большие мускулы и пистолет. Чтобы арестовать бандита, Иван направляется в Чикаго — рассадник капиталистической заразы.",
 "f-wd57177410": "Харли Квинн рассталась с Джокером и через некоторое время сообщила об этом всему Готэму, взорвав тот самый химзавод. Девушка больше не тоскует по несостоявшимся отношениям - ей некогда, так как она также потеряла неприкосновенность, и теперь за ней охотятся разной степени криминализованности граждане, желающие отомстить. А в это время ставший крёстным отцом Готема Роман Сайонис очень жаждет вернуть пропавший бриллиант, который стащила у его подручного малолетняя карманница.",
 "f-wd1624872": "Эксперименты по достижению невидимости человека увенчались успехом: военные, мечтавшие об идеальном шпионе и диверсанте, в полном восторге. Но ученым так и не удалось справиться с побочными эффектами новой технологии — у невидимок резко повышается уровень агрессии и психической нестабильности.В один ужасный день очередной подопытный по имени Майкл Гриффин выходит из-под контроля и вырывается на свободу. Лишь два человека, знающие тайну незримого убийцы — Френк Тернер и биолог Мэгги Далтон — способны остановить его. Однако спецслужбы вовсе не желают быть уличенными в том, что выпустили на свободу невидимого монстра. И готовы на все, чтобы заставить героев замолчать навеки — как и сам Гриффин…",
 "f-wd1507513": "Они спали целых двести лет. Но теперь они проснулись, и им очень хочется есть. И, надо заметить, голод у них за два века развился нешуточный! Подземные твари вылезают на поверхность и отправляются в путешествие по просторам Невады в поисках своего завтрака. На пути прожорливых монстров оказывается знакомый нам городок под скромным названием «Совершенство». Но здесь уже готовы к «приему» ползучих людоедов! Признанный специалист по выживанию и профессиональный истребитель страшных хищников, Берт Гаммер, успел обзавестись огромным арсеналом всевозможного стрелкового оружия, различной взрывчатки и готов к бою на все сто. Правда он еще не знает, что подземные черви тоже подготовились к встрече с городом: они научились превращаться в чрезвычайно опасных летающих особей…",
 "f-wd1433571": "Гигантские черви «грабоиды» возвращаются, чтобы превратить Землю в большой шведский стол. Пока что древние хищники из прекембрийского периода довольствуются случайными странниками и рабочими, оказавшимися в мексиканской пустыне. Но аппетиты тварей растут с каждым днем. Бизнесмен Карлос Ортега решает положить конец беспределу гигантских червей и отправляется в штат Невада на поиски Эрла Бассета, того самого смельчака, которому удалось убить нескольких червей…",
 "f-wd1710012": "По дороге в Лас Вегас на рок-концерт у четвёрки друзей ломается машина. Решив позаимствовать чужой автомобиль, они и не подозревали, что он на самом деле принадлежит маньяку по кличке Ржавый ноготь, которого факт пропажи транспортного средства сильно опечалил.",
 "f-wd694533": "Господин Землемер приглашен Замком для ведения соответствующих работ. Прибыв в Деревню, он с удивлением обнаруживает, что здесь его никто не ждет. Попытки доказать свои права наталкивается на стену непонимания. Желание проникнуть в загадочный Замок все сильнее овладевает героем…",
 "f-wd1129069": "2021 год. Самый ценный товар — информация, доставляемая курьерами в их собственном мозгу. Чтобы преуспеть в этом бизнесе, Джонни стёр воспоминания детства и расширил память, но этого всё равно оказалось мало для того объёма информации, который он взялся доставить. Если её вовремя не выгрузить, то Джонни погибнет. Ставки велики, и информацию желают получить вездесущие якудза, подключающие к делу убийцу по кличке Проповедник.",
 "f-wd28664585": "Юную Машу мучают видения летающих огненных монстров. Мама переживает за дочь, одноклассники посмеиваются. Но однажды в самом центре Москвы Маша видит наяву сражение крылатых огненных чудовищ с молодыми людьми, которые называют себя магами. Один из них в последний момент, спасает Машу от нападения химеры. Так Маша попадает в секретную корпорацию, где узнаёт, что Дед Мороз реально существует и, возглавляя армию магов, способных управлять снегом и льдом, охраняет Землю от вторжения темных сил.  А новогодний праздник — это магический ритуал, который каждый год совершают люди на всей планете, даже не подозревая, что участвуют в самой масштабной битве добра и зла. Дед Мороз сообщает Маше, что судьба нашего мира висит на волоске, и от Маши зависит, кто победит — свет или тьма.",
 "f-wd16155099": "Секретная правительственная организация формирует группу «Отряд Самоубийц», состоящую из наемников и убийц, чтобы проникнуть в психиатрическую лечебницу Аркхэм и добыть похищенную засекреченную информацию, из рук заключенного — Эдварда Нигмы «Загадочника».",
 "f-wd116728278": "Леон Кеннеди расследует загадочные нападения, в результате которых люди заражаются неизвестным вирусом и теряют рассудок. След приводит его к острову Алькатрас, где скрывается опасная тайна. Тем временем Крис, Джилл, Клэр и Ребекка занимаются расследованием вспышки, связанной с новым биологическим оружием. Вскоре герои оказываются на одном острове и объединяются, чтобы остановить террориста, намеренного использовать смертельный вирус для уничтожения Сан-Франциско.",
 "f-wd150044": "Леон отправляется в раздираемую гражданской войной Восточную Европу, где появляются свидетельства использования биологического оружия. Оказавшись втянутым в опасное противостояние, он сталкивается с Лизой Гамильтон и загадочными существами, созданными с помощью вирусов. Тем временем Крис и его отряд пытаются остановить распространение биологического оружия и раскрыть тайну новых монстров. Леону предстоит пережить жестокую схватку, в которой на кону оказываются жизни мирных жителей и судьба целой страны.",
 "f-wd21529463": "1609 год. Идет война. Польско-литовские войска взяли в осаду Смоленск, но русский гарнизон во главе с воеводой Михаилом Шеиным готов держать оборону до конца. Смоленск — главная крепость на пути захватчиков к Москве, и его нельзя сдавать без боя. Об этом знают даже дети.  Мальчик Сашка лепит самодельные бомбы из теста и колдует в защиту города — вызывает на помощь Царя с Огненным щитом и Пламенным копьем. Пока волшебный царь не пришел, Сашка и его друг Федор просятся в помощники к воеводе. Им предстоит разрушить коварные планы польского короля Сигизмунда Третьего и справиться с нечистой силой, что по ночам бродит по осажденной крепости.",
 "f-wd116834076": "Царь собирается выдать свою дочь Забаву за красавца Поля, единственного наследника богача Полкана. Вот только царевна хочет выйти замуж по любви. Её неожиданное знакомство с простым, но честным и обаятельным матросом Иваном вносит смуту в планы хитреца Поля заполучить корону. И если в руках злодея тёмная магия и богатство, то на стороне Ивана — волшебные существа, любовь и мечта.",
 "f-wd272595": "В далеком будущем полярные снега растаяли, покрыв практически всю Землю водой. И хотя ходят легенды, что где-то остался кусочек пригодной для жизни суши, её до сих пор никто не смог найти.\r На Атолл приплывает Моряк. Он хочет продать землю, добытую при нырянии, но его принимают за шпиона «курильщиков» – самых опасных бандитов Водного мира. При помощи девушки Хелен и маленькой девочки Энолы ему удается избежать казни. Взамен Хелен просит отвезти их на сушу.",
 "f-wd1210947": "Блистательная «черная комедия» о колоритной семейке, обитающей в не менее колоритном доме. Ужасы тонко стилизованы и не внушают страха.Бездна фантазии, юмора, Кристофер Ллойд в роли незадачливого дядюшки Фестера выше всяких похвал! Фильм до сих пор имеет почти культовый успех.",
 "f-wd463313": "Верона стала огромным мегаполисом, Монтекки и Капулетти из дворянских кланов превратились в мафиозные, битвы на мечах теперь заменены уличными перестрелками.Но Ромео и Джульетта так и остались подростками, а божественные строки Шекспира теперь звучат из уст уличных боевиков и наркоманов. Времена меняются, люди меняются, жизнь меняется, а истинная любовь — вечна.",
 "f-wd1139794": "40-летний Энди Стицер добился в жизни многого. У него непыльная и хорошо оплачиваемая работенка в магазине по продаже электронной бытовой техники, хорошие друзья, а также милая квартирка, в которой находится гордость Энди — коллекция игрушечных героев и комиксов. Однако его жизнь лишена простых человеческих радостей, которые доступны большинству людей его возраста. Дело в том, что у Энди никогда не было секса.  Его приятели и коллеги относятся к этому по-разному. Одни считают Энди чудаком, другие же лезут из кожи вон, чтобы помочь ему наверстать упущенное. Но все напрасно. Ничто не может заставить их друга расстаться с девственностью, пока он не встречает 40-летнюю Триш, мать троих детей. Друзья Энди начинают с нетерпением ждать «счастливого события», однако вскоре они с ужасом узнают, что новоявленная парочка решила построить свои взаимоотношения на полном отказе от секса.",
 "f-wd1141746": "Пол Витти — влиятельный нью-йоркский мафиози на грани нервного срыва. Все гангстеры в шоке: как помочь своему чокнутому боссу? Бен Соболь — обычный психоаналитик. У него есть всего несколько дней на то, чтобы помочь крестному отцу справиться с депрессией...",
 "f-wd13573278": "В центре истории — успешный адвокат, который приезжает в родной город на похороны матери и узнаёт, что его отца, городского судью, подозревают в убийстве. Герой решает задержаться, чтобы выяснить правду, и постепенно лучше узнаёт родственников, с которыми давно вообще никак не общался.",
 "f-wd757250": "Львёнка Райана разлучили с его отцом и из нью-йоркского зоопарка отправили на корабле в Африку. Его друзья по зверинцу — коала, крокодил, хамелеон, жираф и белка — решают помочь царю зверей найти сына и, сбежав из зоопарка, отправляются на поиски Райана…",
 "f-wd3222490": "Девушка из провинциального русского городка мечтает стать актрисой, а пока самозабвенно играет Бабу Ягу в городском клубе. Вот там-то и находит ее режиссер, который намерен снять фильм о Жанне д`Арк. Сбывается мечта: ее приглашают на главную роль, и у нее начинается совсем другая жизнь, полная настоящих творческих мук и озарений.",
 "f-wd3411607": "О социально-политическом конфликте двух мировоззрений, о взаимоотношениях младшего и старшего поколений, о вечной борьбе старого и нового, об истинных и ложных ценностях, о созидании и разрушении, о человеческой силе и слабости, о дружбе, любви и одиночестве… Что может быть острее и трагичнее, чем конфликт самых близких друг другу людей, искренне любящих друг друга? Но, увы, такой конфликт неизбежен всякий раз, когда сталкиваются интересы двух поколений.",
 "f-wd4191540": "Двое случайных знакомых, Сергей Пшеничный и Андрей Немчинов, волею загадочных обстоятельств переносятся почти на 40 лет назад. Этот день - 8 мая 1949 года - начинает повторяться для них с неумолимым постоянством. Каждому из героев судьба дает свой шанс: Андрей может предотвратить гибель людей в обветшавшей шахте, Сергей - по-новому взглянуть на своих родителей и понять их.",
 "f-wd51996718": "Две сотни лет назад малороссийские хутора разоряла шайка нехристей-ляхов во главе с могущественным колдуном. С тех пор рыщет в окрестностях Диканьки неизвестный Чёрный Всадник, ловит молодых девушек и жестоко расправляется с ними, будто мстит за что. И следующей его жертвой может стать Лиза. Чтобы спасти возлюбленную, дознователь Николай Гоголь должен разбить злые чары и победить древнее проклятье. Ни одному из смертных ещё не удавалось это. К счастью, на помощь Гоголю приходит гениальный столичный сыщик Яков Гуро, и у него уже есть главный подозреваемый…",
 "f-wd4102803": "По мотивам пьесы А. Вампилова «Прошлым летом в Чулимске». Небольшой таёжный посёлок. Здесь все на виду. И Валентине - 18-летней буфетчице - не скрыть своей любви к приехавшему следователю. Она и не скрывает, а потому и покоряет его жесткий и неуживчивый характер. Но на пути к их счастью - безнадежно влюблённый в неё Павел, который насильно овладевает ею, надеясь, что она станет его женой...",
 "f-wd4425681": "Аристократка девятнадцатого века, Графиня Призорова, живет в Москве. Она богата, молода, но с некоторых пор ей стали сниться очень странные сны. Будто она не графиня, а уборщица Маша Степанова, работает в Москве, в 1993 году, в столовой № 9. Она лимитчица из глубинки и живет в общежитии. Не найдя объяснений столь странным сновидениям, графиня обращается к доктору.",
 "f-wd58874611": "1988 год. Афганская война заканчивается, но путь наших солдат домой лежит через опасные территории, которые контролируют моджахеды. Молодой лейтенант Василий Железняков по прозвищу Грек отважен и находчив и сразу привлекает к себе внимание службы разведки. Теперь от него зависит безопасный проход через перевал, который контролирует один из самых жестоких бандитов. Чтобы дивизия вернулась на родину с наименьшими потерями, Греку придется самому остаться у него в заложниках. Цена любой его ошибки — жизнь. Фильм основан на реальных событиях.",
 "f-wd21684007": "1985 год. Навстречу ледоколу «Михаил Громов» движется огромный айсберг. Уходя от столкновения с ним, судно попадает в ледовый плен и оказывается в вынужденном дрейфе вблизи побережья Антарктиды. Вокруг зловещая тишина и жуткий холод. Горючее на исходе... Нервы на пределе... И даже если можно было бы уйти - деваться всё равно некуда. У командования ледокола нет права на ошибку. Одно неверное решение - и тяжёлые льды раздавят судно...",
 "f-wd108550685": "История этой непростой картины начинается в небольшом поселке под Нальчиком. У Тони − водителя рейсового автобуса на войне в Сирии погибает единственный сын, завербовавшийся в ЧВК. Женщина не хочет верить в смерть сына, пока сама не увидит его тела. Представители ЧВК настаивают, что трагедия на самом деле произошла, но ни военкомат, ни милиция, ни городская администрация не способны ничем помочь матери (что естественно). Тоня пытается добиться расследования, но это только усугубляет ее положение. Однако жизнь Тони и всего поселка переворачивается, когда на пороге ее дома появляется молодой солдат, который представляется её сыном...",
 "f-wd109942735": "История о подвиге лётчиков 1-го минно-торпедного авиационного полка ВВС Балтийского флота во главе с полковником Преображенским. У них была сложнейшая боевая задача — нанести первые бомбовые удары по Берлину, столице фашистской Германии.",
 "f-wd17563594": "Однажды появляется неизвестный странник в необычном одеянии - человек в странной экипировке, неустанно твердящий, что он \"не из этих мест\". Так начинается необыкновенная история, но прочно связавшая друг с другом путешествия во времени и в пространстве, грандиозные сражения и героические подвиги, волшебство и древнюю магию, пророчества и их чудесное воплощение в реальность.",
 "f-wd4515045": "По одноимённой пьесе Константина Симонова.  Американский журналист волею обстоятельств поставлен перед нелегким выбором: предать огласке преступные планы сторонников войны и при этом лишиться всех жизненных благ или отступить...",
 "f-wd128798957": "Любительница животных Мейбл использует умную новуютехнологию, предназначенную для «перескакивания» человеческого сознанияв реалистичных роботизированных животных, чтобы общаться с бобрами, раскрывая тайны животного мира, которые она даже не могла себе представить.",
 "f-wd115917655": "Таинственный путешественник пытается заставить сотрудника службы безопасности аэропорта пропустить опасный предмет на рождественский рейс. Успеет ли тот его перехитрить?",
 "f-wd134430061": "В футуристическом мегаполисе объявляется Кожаный человек — монстр, рожденный болью и женскими страхами. Он приходит из розового тумана, чтобы убивать девушек. Случайными свидетельницами его последнего преступления становится известная актриса и ее подруга-блогерша. И если раньше девушкам приходилось биться за превосходство друг с другом, то теперь их жизни превращаются в борьбу за выживание, ведь монстр может прийти за каждой. Также в розовый ад отправляется рядовой Кей, который потерял там свою дочь, но неожиданно нашел одну из девушек.",
 "f-wd29348620": "Рассказ о двух кадетах суворовского училища, отправленных в Шотландию ради спасения русских сирот из лап оккультистов.",
 "f-wd130566333": "Панк-вселенной «Короля и Шута» грозит гибель. Сказочный мир рушится под поступью мертвецов, воскрешенных безумным Некромантом. Одолеть злодея не дано никому, кроме его создателей — друзей, разделенных смертью… Горшка и Князя.",
 "f-wd107435219": "Как быть сыну, родители которого каждый день задают вопрос, кого он любит больше — маму или папу? Как быть маме, если она безумно любит сына, но обстоятельства вынуждают отнять ребёнка у его отца? Как быть папе, если его сына увозят в Америку навсегда, а он не представляет своей жизни без него? Это история о выборе. Родители, решая за своих детей, чаще делают так, как удобно им. Ребёнок соглашается, боясь причинить боль, но пройдёт время, он созреет и в какой-то момент обязательно решит сам. Только родителям от этого будет намного больнее.",
 "f-wd4302250": "Первая мировая война. Старший лейтенант Артеньев - храбрый, волевой офицер, человек чести. Он любит и любим, но его любимая - Клара - работает на контрразведку и быть вместе они не могут... Не поддерживая бунтарских настроений матросов на своем корабле, Артеньев берет на себя командование батареей, защищающей самое опасное место в обороне против немцев.",
 "f-wd4362601": "«Тройка, семерка, туз — не выходили из его головы и шевелились на его губах. …Тройка, семерка, туз — преследовали его во сне, принимая все возможные виды… Все мысли его слились в одну, — воспользоваться тайной, которая дорого ему стоила.»",
 "f-wd124364758": "Семейный отдых Кабира оказывается испорчен после того, как на пороге его дома появляется загадочный незнакомец.",
 "f-wd122931574": "Пренебрегающий правилами полицейский застреливает подозреваемого при задержании. Чтобы оправдать свой поступок и раскрыть преступление ему придется объявить войну системе.",
 "f-wd125207809": "Решив сделать предложение любимой, чей влиятельный отец уже помолвил дочь с другим и теперь везёт всю семью на свадьбу в Нью-Дели, спецназовец Амрит вместе с сослуживцем садится в тот же поезд. Внезапно состав подвергается ограблению, и теперь боевым товарищам с голыми руками придётся противостоять многочисленным бандитам, вооружённым всевозможным колюще-режущим инвентарём.",
 "f-wd116413183": "Известного писателя и профессора литературы Телониуса «Монка» Эллисона критикуют за то, что его работы «недостаточно чёрные». В попытке завоевать внимание аудитории он пишет анонимный роман, вобравший в себя все стереотипы о темнокожем населении США. Книга моментально становится сенсацией, и теперь Монку придётся лично мириться с масштабными последствиями.",
 "f-wd135393743": "Ранджан, романтичный юноша из маленького городка Банарас, устраивается на государственную работу, чтобы жениться на Титли. Но парень забывает о своей клятве Шиве и попадает в ловушку, выбраться из которой он не сможет, пока не выполнит свое обещание.",
 "f-wd674887": "С юным Кимбли случилась неприятность: отправляясь на свидание к любимой девушке, он забыл захватить с собой… презерватив. Со скоростью олимпийского спринтера он бросается на поиски.  И тут начинается комедийная одиссея, в ходе которой, после самых неожиданных встреч и приключений, он в конце концов находит нечто более ценное, чем презерватив. А именно — свою настоящую любовь…",
 "f-wd126126903": "Арул в молодости вместе со своей семьей вынужден был покинуть родной город из-за спора с наследством. И теперь спустя 22 года, Арул приезжает в родные края на свадьбу сестры, и встречает там родственника крайне доброжелательного, но навязчивого. Незнакомец относится к нему со всей любовью и знает о нем всё, но Арул так и не может вспомнить его.",
 "f-wd126877461": "В этом фильме на основе реального судебного разбирательства смелый журналист выступает против влиятельного аморального лидера.",
 "f-wd858681": "Раджу вынужден жить на улице, так как в детстве его отец бросил мать, и они остались на улице. Он пытается убить отца, но терпит неудачу. И теперь должен предстать перед судом, а защищать его решается его подруга детства.",
 "f-wd485676": "Ананд Сайгал старается брать от жизни все. Он наслаждается буквально каждым моментом своей жизни, принимая каждый новый день, как дар свыше. Доктор Бхаскара Банерджи, благодаря знакомству с Анандом, написал книгу, которая дала ему возможность получить очень престижную награду. Ананд Сайгал полностью изменил к лучшему жизнь доктора, когда тот переживал очень серьезный жизненный кризис.",
 "f-wd1546398": "Бедная крестьянка Лакшми живет вместе с глухонемым мужем в небольшой индийской деревушке. Вместе с ним она работает на богатого землевладельца. Сын богача Сария бросает учебу и возвращается домой, чтобы следить за поместьем и жениться на девушке Сарой, с которой они помолвлены с раннего детства.",
 "f-wd1296280": "Аджай - сын индийского олигарха. Раджа - нищий автомеханик. Мадху - дочь богатого бизнесмена. Каджол - девушка из бедных индийских слоев общества. Родители Аджая и Мадху мечтают пристроить своих детей в такие же богатые, как и они семьи. Да только судьба распорядилась по-другому. Богач Аджай влюбился в босячку Каджол, а шикарная невеста Мадху вдруг обратила свой взор на бедного «принца» Раджу. Как только молодые люди заявили о своих планах родителям, так сразу же завертелся маховик ответной «реакции» отцов и матерей...",
 "f-wd28180128": "Индийский премьер-министр Нарендра Моди запустил общественную кампанию «Чистая Индия», задача которой — отучить индийский народ гадить посреди улицы. Согласно традиции, нельзя иметь в доме специальное отхожее место, ведь дом от этого становится «нечистым», поэтому кампания продвигается со скрипом.  Очень неприятный сюрприз обнаруживает Джайя в первую брачную ночь. Оказывается, у её новоиспеченного мужа нет туалета. Хочешь по большой нужде — вставай пораньше и иди в поле. К счастью, на дворе 2017 год, поэтому молодая невеста решает поднять бунт.",
 "f-wd717188": "Основные действия картины «Дом и мир» разворачиваются в доме богатого землевладельца Нихила, в начале ХХ века. Нихил живет богато и очень счастливо, он женат на прекрасной женщине Бимале, с которой у них полное взаимопонимание. Но однажды в его доме появляется революционер Сандил. Трагическая история любви Сандила и Бималы не оставят никого равнодушными",
 "f-wd3630260": "Панду — отъявленный бандит. Он вступает в банду к Али Бхаю, Дону земельной мафии. Но встречает на своем пути Шрути и влюбляется в нее. Шрути тоже полюбила его, но не может смириться с его «профессией». Что победит, любовь или смерть? И что является правдой?",
 "f-wd3292224": "Три брата Шанкар , Виджай и Ратан были разлучены в детстве, когда их родителей безжалостно расстрелял наемный убийца. Мальчики выросли в разных условиях. Старший - Шанкар - вырос из простого карманника до босса преступного мира. Виджая подобрал на улице бедный старик. Скромная и небогатая вдова посвятила всю свою жизнь самому младшему из братьев - Ратану, он вырос и стал популярным эстрадным певцом. Все силы Шанкар отдал поискам убийцы своих родителей. И в конце концов он нашел его и безжалостно уничтожил.",
 "f-wd1549137": "Маленький мальчик, служа в доме бессердечного богача, влюбляется в его дочь, маленькую Камну. Отец Камны, прознав про это, выгоняет верного слугу. Проходят годы. Некогда верный слуга, Сикандар, - ныне богатый человек, встречает свою госпожу Камну и в нем расцветает чувство любви. Но Камна любит другого - его верного друга Вишала...",
 "f-wd112182731": "Выросший в атеистической семье молодой человек Виплав влюбляется в красавицу Аарадью с первого взгляда. Девушка оказывается из консервативной семьи брахманов, но это не останавливает пылкого влюбленного. Когда герои узнают, что их отцы давно конфликтуют друг с другом, они решают, что это не станет препятствием для их любви, и женятся вопреки воле родителей. Однако семейная жизнь героев сразу же начинается с проблем.",
 "f-wd3438002": "Эта история любви и жизни известного исполнителя по имени Джанардан Джакхара. Его путь к вершине музыкального олимпа был долог и труден, но, все же, он сумел преодолеть все проблемы и невзгоды и стать настоящей рок-звездой. Он встретил ее еще тогда, когда не был знаменит и популярен. В то время для него было главное стать звездой, и, преследуя свои корыстные цели, он начал встречаться с ней. Но после, как только он добился всего, что хотел, он понял, что это действительно любовь…",
 "f-wd28811017": "Биографический фильм рассказывает об актере Санджае Датте, его карьере, тюремном заключении и личной жизни.",
 "f-wd115858057": "Опытный гангстер Радха собирается ограбить отделение одного из крупнейших банков в Ченнаи. Вместе с подельниками он намеревается вынести огромную сумму денег, принадлежащих одной крупной корпорации. Когда Радха оказывается внутри, он с ужасом обнаруживает, что банк уже захвачен человеком, известным под прозвищем Майкл Джексон. Двум преступным лидерам предстоит заключить соглашение и попытаться вместе выбраться из уже окружённого спецназом здания. Когда выясняется, что в хранилище находится не 5000 крор, а всего 1510, Радха решает убить Джексона, но попытка покушения оборачивается неудачей. Чем завершится это ограбление и удастся ли преступникам выскользнуть из сложившейся ситуации?",
 "f-wd1314177": "Ведущий кулинарного телешоу в Мельбурне Джеки случайно становится обладателем видеокассеты с записью кровавой разборки между бандами наркоторговцев. На этом спокойные дни для Джеки закончились и превратились в бесконечную гонку на выживание. Он бы с удовольствием отдал кассету бандитам или полиции, ведь на ней улика. Но те не задавали вопросов, а у Джеки все равно не было ответов. Зато было тренированное тело и молниеносные кулаки.",
 "f-wd253565": "Искусный и быстрый, как молния, мастер восточных боевых искусств Чен Жен возвращается в свою бывшую школу, где его ждёт страшная новость. Зверски убит глубоко почитаемый наставник, преподававший кун-фу и карате. Действие происходит в 1908 году в оккупированном японцами Шанхае. Нападение на школу и убийство учителя было организовано одной из японских школ бушидо. Зная, что власти и пальцем не пошевелят, чтобы привлечь преступников к ответственности, Чен Жен обрушивает на злодеев свой кулак ярости.",
 "f-wd73093255": "В детстве переболев заболеванием опорно-двигательного аппарата, Лаал откроет в себе удивительные способности к бегу, отправится на войну, получит ранение, станет звездой спорта, повстречается с великими людьми своего времени и совершенно случайно заработает состояние. И через всю жизнь пронесет светлое чувство к подруге детства.",
 "f-wd879174": "Разведенный отец двоих детей Уксбаль — свой человек в теневом мире Барселоны. Для правоохранительных органов он — нарушитель закона; для нелегальных иммигрантов, которым помогает получить работу, — добрый ангел. Узнав, что неизлечимо болен, Уксбаль начинает готовиться к смерти, размышляя о минувшем и улаживая дела в настоящем. И тут за расследование преступной деятельности героя берется его друг детства, а ныне — офицер полиции…",
 "f-wd17125101": "Невероятная история Бена и его сестрёнки Сирши. Вместе они пускаются в фантастическое путешествие сквозь исчезающий мир древних легенд и магии.",
 "f-wd1193655": "Канун Нового года. Трое пьяниц вспоминают легенду. Она гласит о том, что последний страшный грешник, который умрет в текущем году, должен будет целый год водить призрачную повозку, которая возит души мертвецов.",
 "f-wd1194546": "Экранизация одноименного шедевра мировой литературы, великого русского философа и писателя Ф. М. Достоевского. Действие перенесено на Хоккайдо, самый северный из японских островов.\r Камэда возвращается на Хоккайдо. В трюме парохода он встречается с новоиспечённым миллионером Акамой, в высшей степени темпераментным человеком. Акама рассказывает о своей роковой страсти к красавице Тэко Насу…",
 "f-wd166588": "Действие фильма развивается в первой трети ХХ века на северо-востоке Китая. Юную Цзюцзи насильно выдают замуж за больного проказой старика – владельца винокурни. Ее уже несут в красном свадебном паланкине, но один из носильщиков паланкина, молодой и отважный Ю, похищает девушку и тем самым спасает ее от столь незавидной участи. Связав свою судьбу, молодые герои становятся хозяевами винокурни, где производится чудодейственный напиток – крепкое гаоляновое вино, бодрящее дух и исцеляющее многие болезни. Мирную жизнь прерывает вторжение японцев. Вместе с односельчанами Ю и Цзюцзи встают на защиту родных гаоляновых полей. Земля орошается огненно-красным вином и кровью...",
 "f-wd494410": "На фоне трагических событий корейской войны 1950-53 годов - самой кровопролитной после окончания Второй мировой, показана судьба одной семьи. Мирное благополучие, счастливые ожидания, мечты и надежды рушатся в единый миг, когда страну охватывает хаос и ужас войны. Под грохот танков, свист пуль и разрывы бомб главный герой фильма Джин-тае пытается спасти своих близких, отправив их на кажущийся спокойным юг Корейского полуострова. Семья, присоединившаяся к колоннам беженцев, заполнивших дороги страны, проходит сквозь лишения и испытания. Но главное несчастье ждало Джин-тае впереди. Его младшего брата силой забрали в солдаты. Джин-тае отчаянно пытался помешать рекрутерам, но сам оказался в поезде новобранцев. Неопытных, необученных, плохо вооруженных парней немедленно забрасывают на передовую. Им приказано держать оборону у реки Накдонг и не сдавать позиций. Для верховного командования они - пушечное мясо. Под шквальным огнем у молодых солдат почти нет шансов выжить...",
 "f-wd1214594": "Джеймс — британский писатель, приезжает в Италию на конференцию, посвященную проблеме подлинников и копий в искусстве. Там он знакомится с француженкой, владелицей картинной галереи, которая делает вид, что писатель — это ее частенько отсутствующий муж. Писатель подыгрывает очаровательной женщине, но эта невинная игра вскоре становится опасной.",
 "f-wd1144590": "Гонконг начала 20 века. На китайском море свирепствуют пираты под предводительством зловещего пирата Ло. Все свои надежды правительство возлагает на специально разработанный план борьбы с пиратами под кодовым названием «Проект А».  Но Ло всегда на шаг опережает власти, подрывает их корабли, и «проект» оказывается под угрозой срыва. Его выполнение берут на себя борец береговой охраны по кличке «Дракон» и его товарищи...",
 "f-wd19824842": "В одинокой долине Исландии живут два брата, вот уже сорок лет они не разговаривают друг с другом. Но им придется нарушить молчание и снова стать одним кланом, чтобы спасти самое дорогое, что у них есть — их баранов.",
 "f-wd704708": "«Вчера будет завтра позавчера» - так говаривали мудрецы-друиды в далёкие-далёкие времена, когда люди считали, что Земля больше всего похожа на пиццу. Тогда был ещё жив Юлий Цезарь, которому и пришла в голову мысль, как римлянам победить свободолюбивых друидов, проживавших в маленькой галльской деревушке.  По приказу императора центурион Люций похитил друида Починикса и отправил его вместе с псом Догматиксом на край света. Но за ними следом увязалась славная парочка Астерикс и Обеликс...",
 "f-wd386522": "Священник снимает рясу и отправляется в путь, собирая милостыню, когда его обвиняют в том, что он дал приют проститутке, убившей свою коллегу по «работе». Она убегает и присоединяется к нему с другой женщиной, которую бросил любовник. В картине повествуется о скитаниях и попытках помочь человечеству, постоянных неудачах и разочарованиях. Священник понимает, что, для того чтобы стать человеком, тем более священником, необходимо научиться любить людей.",
 "f-wd112977212": "Дания, XVIII век. Для увеличения налоговых поступлений короли пытаются культивировать и заселить огромные болотистые земли Ютландии. Но из-за суровых погодных условий, бедной почвы и большого количества бродяг и преступников все попытки на протяжении десятилетий терпят крах.\r В 1755 году после 25 лет службы капитан датской армии Людвиг Кален уходит в отставку. Не желая заканчивать свои дни в доме для ветеранов, Кален решает заняться освоением болотистых пустошей Ютландии и обращается в королевское казначейство с просьбой об официальном содействии в реализации его планов. Идея вначале не находит поддержки, и Людвигу отказывают в финансировании, но он требует лишь дворянский титул с имением и слугами в случае успеха, после чего получает официальное одобрение казначейства. Прибыв на место и имея за душой лишь небольшую пенсию, бывший военный начинает нанимать людей для строительства и земледелия.",
 "f-wd1043604": "Хореограф Антонио набирает труппу для постановки балета «Кармен». Во время репетиций хореограф поддается чарам настоящей Кармен, которая исполняет главную роль. Музыка и представление так захватывают героев, что правда жизни превращается в спектакль, а само действо ведет к кровавой развязке.",
 "f-wd265203": "Один день из жизни двух совершенно непохожих женщин. Одна из них, еще совсем ребенок, слишком легкомысленна и падка до материальных ценностей, что сводит ее со стариком, страдающим от нереализованной отеческой любви. Другая – наоборот – столь поглощена своим чувством к женатому мужчине, что готова бросить ради него все. Однако обе в конце концов понимают кое-что важное для себя: первая начинает ценить любовь своего молодого человека, вторая же осознает, что есть много других вещей, которые могут дать импульс к жизни.",
 "f-wd3050323": "Автомобиль сбивает человека, в панике убегающего от кого-то или от чего-то. Прибывшие на место полицейские выясняют, что сбитый бедолага — ночной сторож из близлежащего морга. Так что так напугало несчастного? И куда делся из отсека №3 недавно привезенный в морг труп?",
 "f-wd1640085": "Отважный дракон Ма, прославившийся благодаря уничтожению пиратского гнезда на китайском море, получает новое назначение — его делают начальником округа.  Основная причина этого назначения состоит в том, что власти сомневаются в чистоплотности его предшественника Чуна, как оказывается впоследствии, напрасно. В результате мастерски выполненной подставки дракон попадает в тюрьму. Теперь доказать свою невиновность он может только разоблачив Чуна…",
 "f-wd2578176": "1909 год, Мексика. В центре сюжета Мария Канделария и Лоренцо Рафаэль, которые мечтают пожениться. Однако жестокое и полное нетерпимости общество мешает их мечте осуществиться…",
 "f-wd1157372": "Выброшенные на берег небольшого острова ужасным штормом Пауль и Барбара нашли прибежище в заброшенной рыбацкой деревушке. Когда Барбара неожиданно исчезает среди уродливых и отталкивающих местных жителей, Паулю приходится столкнуться с пугающей действительностью одинокого городка. Пауль решается на жуткое расследование исчезновения Барбары в одиночку среди полного бездействия страшных обитателей деревушки. Но то, что обнаруживает Пауль в результате поисков вселяет страх и ужас и грозит опасностью всему миру.",
 "f-wd1193754": "Пять преступников со смешными прозвищами, выйдя из тюрьмы, решают начать честную жизнь и открывают фирму по уборке квартир. Одним из их клиентов оказывается подпольный фальшивомонетчик. В тот самый момент, когда шеф полиции собирался взять фальшивомонетчика с поличным, друзья занимались уборкой в его доме и случайно прихватили чемоданчик с деньгами…",
 "f-wd1353408": "Киллер работал с Агентом три года. Однажды он взял и ушел в пустоту ночных улиц Гонконга. Среди ирреального света фонарей и недосягаемых крыш небоскребов герой встречает странных людей: девушку, ищущую таинственно пропавшего бойфренда, немого торговца, привлекающего внимание покупателей к своим товарам не самым обычным образом.",
 "f-wd1482548": "Сесиль и Йоахим любят друг друга и собираются пожениться. Но все их планы рушатся в одно мгновение: Йоахим попадает под машину и остается полностью парализованным. Сесиль пытается его утешить, но Йоахим пребывает в отчаянии.  Чувствуя свою беспомощность, Сесиль изливает горе доктору Нильсу, жена которого была за рулем автомобиля, сбившего Йоахима. Нильс искренне сочувствует Сесиль, но в своих утешениях заходит слишком далеко. Их дружба перерастает в страстную любовь. И, кажется, Нильс даже рад тому, что его собственная жизнь тоже рушится…",
 "f-wd790112": "В отдаленном будущем человечество осваивает виртуальный мир компьютерной игры под названием «Авалон». Лишь немногим удается достичь в игре финального уровня, а те, кто возвращаются с него, впадают в коматозное состояние, почти не отличающееся от смерти.Чтобы попытаться спасти своего возлюбленного от этой участи, героиня фильма преисполнена решимости пройти всю игру по его стопам и встретиться в финале с загадочным персонажем по имени «Призрак».",
 "f-wd698416": "Холодные ветра подули в сторону далёких северных деревень. Невиданные напасти опустошают людские селенья одно за другим. Призрачные волки, ледяные мамонты и коварные оборотни несут смерть всему живому... И даже закалённые в боях воины не могут противостоять могущественному колдовству демона Грюнвальда, возжелавшего подчинить себе этот суровый край. В это смутное время, в одном из селений появляется отважный мальчик Хольс с загадочным мечём, чьё имя - Солнечный. Еще никто не знает, что его ждут великие битвы и нелёгкая судьба... Но вскоре люди назовут его Принцем Севера!",
 "f-wd19263748": "Девушка потеряла возможность говорить. В детстве по её вине распалась семья, а позже откуда ни возьмись появился дух в виде яйца и, чтобы она больше никого не ранила, «запечатал» её речь.",
 "f-wd28193328": "Известная актриса Ён-хи бежит в Гамбург от неудавшегося с её точки зрения романа с женатым мужчиной. Отдохнув, она возвращается в Корею, встречается со старыми друзьями, много пьёт и пытается разобраться в себе.",
 "f-wd1817757": "Сюжет фильма построен вокруг приключений музыкальной группы из далёкой Сибири, приехавшей в Америку в поисках успеха.\r Музыкальная группа из России сыграна финским коллективом Sleepy Sleepers, который вскоре после выхода фильма также сменил название на «Ленинградские ковбои». Они исполняют свои версии известных рок-н-рольных хитов таких групп, как Creedence Clearwater Revival, The Beatles, Steppenwolf и Элвиса Пресли.",
 "f-wd39073956": "Уиджи — это доска для спиритических сеансов вызова душ умерших. Ее называют доской Дьявола, потому что общение с загробным миром не обходится для живого человека без последствий. Тот, кто берет в руки Уиджи, должен знать, что она обладает страшной властью открывать врата чудовищному злу, противостоять которому практически невозможно. Вероника, красивая и веселая старшеклассница, даже представить не могла, чем для нее закончится то, что она считала невинной игрой. Игра с Уиджи впустила в жизнь девушки не только призрак умершего отца, но и саму Смерть.",
 "f-wd492485": "Интернациональная команда воров экстра-класса планирует грандиозное ограбление в Макао. Все участники банды — опытные профессионалы, бывали в переделках и способны эффективно работать в самых опасных и стрессовых условиях. Однако, несмотря на то, что все роли в безупречном плане преступления четко определены, многие из участников расклада совсем не собираются довольствоваться своей долей и коварно намереваются умыкнуть весь куш. К тому же один из них — полицейский «под прикрытием»…",
 "f-wd17490438": "В фильме рассказывается о непростом периоде, когда в в 1970-х годах в борьбе за контроль над строительством в Каннаме сойдутся политические власти и гангстеры. Друзья детства Чон Тэ и Ён Ки живут в одном из наиболее слаборазвитых районов Сеула и ведут ежедневную борьбу за выживание, пока их хибары не были снесены местными бандитами. Отчаянно нуждаясь в деньгах, парни влазят в разборки и дележ земли (естественно за мизерное вознаграждение) и во время одной из стычек они были разделены. Три года спустя Чон Тэ живет как честный человек, а Ён Ки присоединился к самой могущественной преступной организации Сеула - Мёндон (сейчас квартал Мёндон - центральная торговая улица Сеула). Как гангстер, Ён Ки участвует в битве за земли в Каннам, поставив на карту многое (в частности секретные президентские избирательные фонды). Во время войны между группировками за права на различные участки земли, Ён Ки будет захвачен и допрошен конкурирующей бандой…",
 "f-wd33101534": "В 2004 году в китайском квартале Сеула, печально известном высоким уровнем преступности, объявляются три особо борзых мигранта-коллектора и вместо того, чтобы по старинке изымать деньги у должников, сразу убивают главу одной из преступных группировок. Свято место пусто не бывает, и вот уже предводитель троицы Цзян Чэнь руководит этой бандой и пытается отжать бизнес у конкурентов. Местный начальник следственно-оперативной группы Ма Сок-то привык поддерживать худой мир на подконтрольной территории, но Цзян Чэнь мирно жить не хочет.",
 "f-wd29963333": "Шестилетняя девочка Фрида один за другим теряет отца и мать. Ее увозят из родной Барселоны ее дядя и тетя, которые живут в сельской местности и уже воспитывают четырехлетнюю дочку Анну. Оказавшись в чужой семье и в незнакомой обстановке, Фрида поначалу чувствует себя лишней.",
 "f-wd704780": "Школяр Ку Шен Чай живет в заброшенном форте вместе с матерью — он талантлив и умен, но совершенно лишен амбиций, а оттого беден, как церковная мышь. Однажды в соседний дом въезжает красивая девушка, мисс Янг, которой Ку тут же заинтересовывается, но ведет она себя нелюдимо и в высшей степени странно. В чем же дело — может быть, в этой глуши она скрывается от кого-то? Или вообще родом не из нашего мира?",
 "f-wd19702742": "В огромной вилле, расположенной в фешенебельном районе Копенгагена, Эрик и его жена Анна, воплощая давнюю мечту, создают коммуну близких по духу людей, готовых жить под одной крышей. Общие интересы, беседы, вечеринки полны эйфории и дарят ощущение подлинного единства. До тех пор, пока Эрик не приводит в дом свою новую возлюбленную…",
 "f-wd19896122": "16-летний Ари живет с матерью в Рейкъявике. Ари доволен своей жизнью, но однажды его матери приходится выехать на работу за границу. Парню приходится покинуть столицу и переехать к отцу, в отдаленный район Западных Фьордов, где он бывал ребенком. Отношения с отцом у Ари не лучшие, а друзья детства давно разъехались. Может, что-то изменит появление симпатичной девушки? Ари должен найти себя в этих непростых условиях.\r История о путешествии из детства во взрослую жизнь, об отношениях отца и сына, и о любви — и все это на фоне захватывающих пейзажей Западных Фьордов.",
 "f-wd105658120": "«Борьба со льдом» рассказывает об Эйнаре Миккельсене, в 1909 году отправившемся на поиски останков полярных исследователей, погибших в Гренландии. Пытаясь пройти в труднопроходимую часть острова, Миккельсен берёт с собой только одного помощника, молодого моряка Ивера Иверсена, — и вместе они пытаются выжить и вернуться домой.",
 "f-wd1675241": "Хельге Росс тайком убил быка, принадлежавшего своему хозяину. У крестьянина не было иного выходы - его жена и совсем крошечная дочь должны были что-то есть. Но вскоре Хельге стала мучить совесть. Он отправился на исповедь. Но даже викарий не смог его успокоить, Хельге решил наказать себя за проступок.",
 "f-wd1216772": "История мальчика, который не может смириться с тем, что у него появится брат и с ним придется делиться материнской грудью. Поэтому он обращается к луне с просьбой о том, чтобы она подарила ему титьку только для него.",
 "f-wd1887332": "Два закадычных друга, работающих фотокорреспондентами в горячих точках, готовы рисковать своими жизнями ради сенсационных материалов. Главное, не переступать ту грань, за которой уже нет возврата назад…Отправившись на очередное задание в охваченный войной Курдистан, они попадают в полевой госпиталь, где становятся свидетелями жестокой и циничной «сортировки» раненых — тяжелых «лечат» выстрелами в голову, а остальных пытаются поставить на ноги.",
 "f-wd340300": "Фильм рассказывает о жизни живописца по имени Матису, который не отказывается от своей мечты быть художником, несмотря на отсутствие успеха.",
 "f-wd1916669": "Во время Холодной войны, американским летчикам пришлось сбить неопознанный самолет в небе над Арктикой. Он перевозил атомную бомбу и взрыв пробудил от многовекового сна огромного древнего монстра — огнедышащую черепаху Гамеру. Побуждаемая голодом, Гамера начинает нападать на электростанции и нефтехранилища. Ученые во главе с доктором Хидакой и военные пытаются ее остановить. Однако мальчик Тосио уверен, что Гамера — доброе существо.",
 "f-wd2667089": "Оскар — молодая девушка, отец которой мечтал о мальчике. После рождения дочери он начал одевать её в мужские костюмы и вырастил как сына. Оскар достигает больших успехов в военной карьере и попадает в королевскую гвардию Марии-Антуанетты. В юности Оскар полюбила Андре, сына эконома в их с отцом доме. И теперь, годы спустя, когда начинается Великая французская революция, пути Оскара и Андре снова пересекаются: они сражаются по разные стороны баррикад.",
 "f-wd15284383": "Продолжение истории о похождениях Кэнсина Химуры, некогда легендарного убийцы, вступившего на путь искупления. На этот раз Кэнсин вступает в противостояние с самим Шишио Макото, злодеем, вознамерившимся свергнуть правительство Мэйдзи и подчинить себе всю Японию. Судьба страны висит на волоске, и скиталец-самурай Химура вновь берет в руки меч, к которому он поклялся никогда не прикасаться снова."
};
